# FIRA Multi-Agent System Self-Extractor and Installer
# Run this single script on your local machine to automatically unpack all 10 project files (including the zero-dependency Web Server dashboard) and launch!

import os
import sys
import base64

FILES = {}
FILES["README.md"] = ""
FILES["web_app.py"] = ""
FILES["cli_dashboard.py"] = ""
FILES["audit_logger.py"] = ""
FILES["consensus_engine.py"] = ""
FILES["investor_profile.py"] = ""
FILES["analysts.py"] = ""
FILES["feed_handler.py"] = ""
FILES["knowledge_base.py"] = ""
FILES["requirements.txt"] = "cmljaD49MTMuMC4wCnB5ZGFudGljPj0yLjAuMAo="

def main():
    print('==================================================================')
    print('⚙️  Unpacking Financial Intelligence & Risk Advisor (FIRA) Codebase...')
    print('==================================================================')

    # Write out each file after base64 decoding
    for filename, b64_data in FILES.items():
        try:
            decoded_content = base64.b64decode(b64_data.decode('utf-8') if isinstance(b64_data, bytes) else b64_data).decode('utf-8')
            # Create folder if needed
            dirname = os.path.dirname(filename)
            if dirname and not os.path.exists(dirname):
                os.makedirs(dirname, exist_ok=True)
                
            with open(filename, 'w', encoding='utf-8') as f:
                f.write(decoded_content)
            print(f'  [✓] Created file: {filename}')
        except Exception as e:
            print(f'  [✗] Failed to create {filename}: {str(e)}')
            
    print('\n✨ Unpacking Successful! All 10 project files are extracted inside this folder.')
    print('==================================================================')
    print('🚀 Next Steps to run your system:')
    print('  1. Open Command Prompt/Terminal in this directory.')
    print('  2. Launch your dynamic interactive Web App dashboard (Zero-Dependencies!):')
    print('     python web_app.py')
    print('  3. Or run the terminal CLI simulation:')
    print('     pip install -r requirements.txt')
    print('     python cli_dashboard.py')
    print('==================================================================')

if __name__ == '__main__':
    main()
